def lookup(raw):
    isbn = isbnlib.canonical(raw)
    if not isbn:
        return {"input": raw, "fixed_isbn": "", "title": "", "author": "", "publisher": "", "year": "", "status": "unfixable"}

    for service in ["openl", "goob"]:
        try:
            meta = isbnlib.meta(isbn, service=service)
            if meta and meta.get("Title"):
                return {
                    "input": raw,
                    "fixed_isbn": isbn,
                    "title": meta.get("Title", ""),
                    "author": ", ".join(meta.get("Authors", [])),
                    "publisher": meta.get("Publisher", ""),
                    "year": meta.get("Year", ""),
                    "status": f"found ({service})"
                }
        except Exception:
            continue

    return {"input": raw, "fixed_isbn": isbn, "title": "", "author": "", "publisher": "", "year": "", "status": "not found"}

results = []
for raw in tqdm(broken_isbns, desc="Looking up ISBNs", unit="isbn"):
    results.append(lookup(raw))

with open("isbn_results.csv", "w", newline="", encoding="utf-8") as f:
    writer = csv.DictWriter(f, fieldnames=["input", "fixed_isbn", "title", "author", "publisher", "year", "status"])
    writer.writeheader()
    writer.writerows(results)